{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Donepezil, a dimethoxy-substituted aromatic with a basic N-benzylpiperidine, has complete oral bioavailability (~100%), supporting that the query's dimethoxyaromatic and basic amine motifs can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a tetrabenazine-related benzoquinolizine with a modified side chain, has absolute oral bioavailability of approximately 49%, indicating that structural modification of the low-F tetrabenazine core can raise F above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, the closest structural analog, has very low oral systemic availability (~5%) due to extensive first-pass metabolism; this weighs toward low if the query retains the same metabolic liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a dimethoxytetrahydroisoquinoline with an amide and lipophilic aryl group, has low absolute oral bioavailability (~11%), showing that similar dimethoxy/amide structures can be low.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Verapamil, a dimethoxyphenethylamine with a basic tertiary amine, has absolute oral bioavailability of about 34% in normal conditions, supporting F >= 20% for the query's basic dimethoxyphenyl side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Noscapine, a dimethoxyisoquinoline alkaloid, has absolute oral bioavailability of about 30%, supporting high F for a related dimethoxy-containing scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is structurally closest to tetrabenazine, which has very low F, but it differs by replacing the ketone with a lactam and adding a basic tertiary amine side chain. Multiple related basic dimethoxyaromatic drugs (donepezil, valbenazine, verapamil, noscapine, urapidil) have F >= 20%, so high is better supported.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "The extent to which the lactam and basic side chain alter first-pass metabolism relative to tetrabenazine is unknown.",
    "The query's permeability and metabolic stability have not been directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

